export function nodeDefImplementationSource(prim: Prim): string {
  const v = prim.getAttr('info:implementationSource')?.getValue()
  if (v === 'id' || v === 'sourceAsset' || v === 'sourceCode') return v
  if (v !== undefined && v !== null) {
    console.warn(`Found invalid info:implementationSource value '${String(v)}' on shader ` +
      `at path <${prim.path}>. Falling back to 'id'.`)
  }
  return 'id'
}

// The asset path held by an asset-valued attribute, as a string.
export function assetPathValue(v: unknown): string | null {
  if (v instanceof AssetPath) return v.getAssetPath()
  if (typeof v === 'string') return v
  if (v && typeof v === 'object' && typeof (v as { path?: unknown }).path === 'string') {
    return (v as { path: string }).path
  }
  return null
}

// OpenUSD v26.11.1 nodeDefAPI.cpp:214-376: universal has no source-type
// namespace component; a nonempty token (including "universal") is explicit.
export function sourceProperty(name: string, sourceType: string): string {
  return sourceType ? `info:${sourceType}:${name}` : `info:${name}`
}

